<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/">Home</NuxtLink></li><li>My assigned cases</li></ul></div>
    <header class="rounded-2xl border border-base-200 bg-base-100 p-5 shadow-sm"><div class="flex flex-wrap items-start justify-between gap-3"><div><h1 class="flex items-center gap-2 text-2xl font-bold"><Icon name="lucide:briefcase-business" class="text-primary" />My assigned cases</h1><p class="mt-1 text-sm text-base-content/60">Cases currently assigned to you for specialist preparation, manager review or director approval.</p></div><button class="btn btn-outline btn-sm" :disabled="loading" @click="load"><Icon name="lucide:refresh-cw" :class="loading && 'animate-spin'" />Refresh</button></div><div class="mt-4 flex flex-wrap gap-3"><label class="input min-w-72 flex-1"><Icon name="lucide:search" /><input v-model.trim="search" type="search" placeholder="Search reference, tender or entity" /></label><select v-model="type" class="select select-bordered"><option value="">All templates</option><option value="NEW">New submission</option><option value="RESUBMISSION">Resubmission</option></select></div></header>
    <div class="grid gap-3 sm:grid-cols-3"><div class="stat rounded-xl border border-base-200 bg-base-100 p-4"><div class="stat-title text-xs">Assigned to me</div><div class="stat-value text-2xl">{{ filtered.length }}</div></div><div class="stat rounded-xl border border-base-200 bg-base-100 p-4"><div class="stat-title text-xs">New submissions</div><div class="stat-value text-2xl text-primary">{{ countType('NEW') }}</div></div><div class="stat rounded-xl border border-base-200 bg-base-100 p-4"><div class="stat-title text-xs">Resubmissions</div><div class="stat-value text-2xl text-warning">{{ countType('RESUBMISSION') }}</div></div></div>
    <div v-if="loading" class="flex justify-center py-16"><span class="loading loading-spinner loading-lg" /></div>
    <div v-else class="overflow-x-auto rounded-2xl border border-base-200 bg-base-100"><table class="table"><thead><tr><th>Case</th><th>Template</th><th>Current task</th><th>Priority</th><th>Assigned</th><th /></tr></thead><tbody><tr v-for="row in filtered" :key="row.uuid"><td><p class="font-semibold">{{ row.tender?.title }}</p><p class="text-xs text-base-content/55">{{ row.reference_number }} · {{ row.tender?.tendernumber }}</p><p class="text-xs text-base-content/55">{{ row.tender?.company?.name }}</p></td><td><span :class="['badge badge-sm', row.submission_type === 'RESUBMISSION' ? 'badge-warning' : 'badge-info badge-outline']">{{ templateName(row) }}</span></td><td><p class="font-medium">{{ taskLabel(row.status) }}</p><p class="text-xs text-base-content/50">{{ statusHelp(row.status) }}</p></td><td><span :class="['badge badge-sm', priorityClass(row.priority)]">{{ priorityLabel(row.priority) }}</span></td><td class="text-sm">{{ date(row.latest_stage_event?.occurred_at || row.assigned_at || row.submitted_at) }}</td><td><NuxtLink :to="`/spoc-submissions/${row.uuid}`" class="btn btn-primary btn-sm"><Icon name="lucide:play" />Start work</NuxtLink></td></tr><tr v-if="!filtered.length"><td colspan="6" class="py-14 text-center text-base-content/45"><Icon name="lucide:inbox" class="mx-auto mb-2 h-7 w-7" />No cases are currently assigned to you.</td></tr></tbody></table></div>
  </div>
</template>
<script setup>
definePageMeta({ layout: 'default' }); useHead({ title: 'My assigned SPOC cases' });
const api = useSpocWorkflowHelper(); const toast = useToast(); const { guardPage } = useCheckPermission(); const rows = ref([]); const loading = ref(false); const search = ref(''); const type = ref(''); const currentYear = new Date().getFullYear();
const filtered = computed(() => { const term = search.value.toLowerCase(); return rows.value.filter(row => (!type.value || row.submission_type === type.value) && (!term || [row.reference_number, row.tender?.title, row.tender?.tendernumber, row.tender?.company?.name].some(value => String(value || '').toLowerCase().includes(term)))); });
const countType = value => filtered.value.filter(row => row.submission_type === value).length;
const templateName = row => row.submission_type === 'RESUBMISSION' ? 'Resubmission Evaluation' : 'New Submission Evaluation';
const taskLabel = status => ({ ASSIGNED_FOR_CASE_CREATION: 'Prepare specialist assessment', MANAGER_REVIEW: 'Review specialist case', AWAITING_APPROVAL: 'Approve internal recommendation', AWAITING_AGENDA: 'Prepare agenda placement' }[status] || String(status || '').replaceAll('_', ' '));
const statusHelp = status => ({ ASSIGNED_FOR_CASE_CREATION: 'Complete the relevant evaluation template.', MANAGER_REVIEW: 'Endorse, amend or return with reasons.', AWAITING_APPROVAL: 'Endorse for agenda or return to manager.', AWAITING_AGENDA: 'Case is ready for committee scheduling.' }[status] || 'Open the case to continue.');
const priorityLabel = value => ({ HIGH: 'High Priority', URGENT: 'Urgent', EXTREME: 'Extreme Priority' }[value] || 'High Priority'); const priorityClass = value => ({ HIGH: 'badge-info badge-outline', URGENT: 'badge-warning', EXTREME: 'badge-error' }[value] || 'badge-info badge-outline');
const date = value => value ? new Date(value).toLocaleString('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }) : '—';
const load = async () => { loading.value = true; const { data, error } = await api.myAssigned({ year: currentYear }); loading.value = false; if (error) return toast.error({ title: 'Could not load assigned cases', message: error?.data?.message || 'Please try again.' }); rows.value = data?.data ?? []; };
onMounted(async () => {
  if (!await guardPage('can.access.myspoccases', 'You are not permitted to access My Assigned Cases.')) {
    return navigateTo('/');
  }
  await load();
});
</script>
